import { useCallback, useEffect, useState } from 'react';
import clsx from 'clsx';
import { Phone, Scissors } from 'lucide-react';
import './index.css';
import type { Draft, Route } from './lib/types';
import { useStore } from './lib/store';
import { todayKey } from './lib/dates';
import { SHOP } from './data/catalog';
import Home from './components/Home';
import Booking from './components/Booking';
import MyAppointments from './components/MyAppointments';
import Agenda from './components/Agenda';
import { Pole, Toast } from './components/ui';

const ROUTES: { id: Route; label: string; short?: string }[] = [
  { id: 'inicio', label: 'Inicio' },
  { id: 'reservar', label: 'Reservar' },
  { id: 'mis-citas', label: 'Mis citas' },
  { id: 'agenda', label: 'Agenda del día', short: 'Agenda' },
];

export const EMPTY_DRAFT: Draft = { step: 0, serviceId: null, barberId: null, date: null, start: null, rescheduleId: null };

function readRoute(): Route {
  const h = window.location.hash.replace(/^#\/?/, '') as Route;
  return ROUTES.some(r => r.id === h) ? h : 'inicio';
}

export default function App() {
  const store = useStore();
  const [route, setRoute] = useState<Route>(readRoute);
  const [draft, setDraft] = useState<Draft>(EMPTY_DRAFT);
  const [toast, setToast] = useState<string | null>(null);

  useEffect(() => {
    const on = () => setRoute(readRoute());
    window.addEventListener('hashchange', on);
    return () => window.removeEventListener('hashchange', on);
  }, []);

  const go = useCallback((r: Route) => {
    setRoute(r);
    try { window.history.replaceState(null, '', `#/${r}`); } catch { /* vista previa sin historial */ }
    window.scrollTo({ top: 0 });
  }, []);

  /** Abre el asistente con parte de la reserva ya elegida. */
  const startBooking = useCallback((partial: Partial<Draft> = {}) => {
    const d = { ...EMPTY_DRAFT, ...partial };
    if (partial.step === undefined) d.step = d.serviceId ? (d.barberId ? 2 : 1) : 0;
    setDraft(d);
    go('reservar');
  }, [go]);

  const upcoming = store.appts.filter(a => a.mine && a.status === 'confirmada' && a.date >= todayKey()).length;
  const closeToast = useCallback(() => setToast(null), []);

  return (
    <div className="nv min-h-screen bg-[#EFEEEA] text-[#17191B]">
      <header className="sticky top-0 z-40 bg-[#17191B] text-white">
        <div className="mx-auto flex max-w-6xl items-center gap-6 px-4 sm:px-6">
          <button onClick={() => go('inicio')} className="flex shrink-0 items-center gap-2.5 py-3.5" aria-label="Navaja & Co., ir al inicio">
            <span className="grid h-9 w-9 place-items-center rounded-full border border-[#B88A3E]/70 text-[#D9B26A]">
              <Scissors size={17} />
            </span>
            <span className="nv-serif text-[22px] leading-none">Navaja <span className="italic text-[#D9B26A]">&amp;</span> Co.</span>
          </button>
          <nav className="hidden flex-1 items-center gap-1 md:flex" aria-label="Secciones">
            {ROUTES.map(r => (
              <NavBtn key={r.id} active={route === r.id} onClick={() => (r.id === 'reservar' ? startBooking() : go(r.id))} label={r.label} badge={r.id === 'mis-citas' ? upcoming : 0} />
            ))}
          </nav>
          <a href={`tel:${SHOP.phone.replace(/\s/g, '')}`} className="ml-auto hidden items-center gap-2 text-sm text-white/75 hover:text-white lg:flex">
            <Phone size={15} /> {SHOP.phone}
          </a>
        </div>
        <nav className="nv-scroll flex gap-1 overflow-x-auto border-t border-white/10 px-3 py-1.5 md:hidden" aria-label="Secciones">
          {ROUTES.map(r => (
            <NavBtn key={r.id} active={route === r.id} onClick={() => (r.id === 'reservar' ? startBooking() : go(r.id))} label={r.short ?? r.label} badge={r.id === 'mis-citas' ? upcoming : 0} />
          ))}
        </nav>
        <Pole className="h-1.5" />
      </header>

      <main key={route} className="nv-in pb-24">
        {route === 'inicio' && <Home store={store} onBook={startBooking} />}
        {route === 'reservar' && (
          <Booking store={store} draft={draft} setDraft={setDraft} go={go} notify={setToast} />
        )}
        {route === 'mis-citas' && <MyAppointments store={store} onBook={startBooking} notify={setToast} />}
        {route === 'agenda' && <Agenda store={store} notify={setToast} />}
      </main>

      {toast && <Toast message={toast} onClose={closeToast} />}
    </div>
  );
}

function NavBtn({ active, onClick, label, badge }: { active: boolean; onClick: () => void; label: string; badge: number }) {
  return (
    <button
      onClick={onClick}
      aria-current={active ? 'page' : undefined}
      className={clsx(
        'flex shrink-0 items-center gap-2 rounded-full px-3.5 py-2 text-sm font-medium transition-colors',
        active ? 'bg-white/10 text-white' : 'text-white/65 hover:text-white',
      )}
    >
      {label}
      {badge > 0 && <span className="grid h-5 min-w-[20px] place-items-center rounded-full bg-[#C99A4A] px-1.5 text-[11px] font-bold text-[#17191B]">{badge}</span>}
    </button>
  );
}

import { useEffect, useMemo, useState } from 'react';
import clsx from 'clsx';
import { Ban, CalendarX2, Check, ChevronLeft, ChevronRight, Globe, MessageSquareText, Phone, Store as StoreIcon, UserX, X } from 'lucide-react';
import type { AgendaItem, Status } from '../lib/types';
import type { Store } from '../lib/store';
import { BARBERS, barberById, serviceById } from '../data/catalog';
import { dayItems, hoursFor, isWorking } from '../lib/schedule';
import { addDays, diffDays, hhmm, money, nowMinutes, relDay, todayKey } from '../lib/dates';
import { Avatar, Btn, StatusChip } from './ui';

type Props = { store: Store; notify: (m: string) => void };
const PX = 1.6; // píxeles por minuto

const BLOCK: Record<Status, string> = {
  confirmada: 'bg-[#E3ECE7] border-[#1E3A31] text-[#17191B]',
  atendida: 'bg-[#ECEAE5] border-[#9A9C98] text-[#4A4D4F]',
  'no-show': 'bg-[#F6E1DE] border-[#B23A32] text-[#7A241E]',
  cancelada: 'hidden',
};
const SOURCE_ICON = { web: Globe, 'teléfono': Phone, 'en local': StoreIcon };

export default function Agenda({ store, notify }: Props) {
  const [date, setDate] = useState(todayKey());
  const [selId, setSelId] = useState<string | null>(null);
  const [now, setNow] = useState(nowMinutes());
  useEffect(() => { const t = setInterval(() => setNow(nowMinutes()), 60000); return () => clearInterval(t); }, []);

  const h = hoursFor(date);
  const items = useMemo(() => dayItems(date, store.appts, store.overrides), [date, store.appts, store.overrides]);
  const active = items.filter(i => i.status !== 'cancelada');
  const cancelled = items.filter(i => i.status === 'cancelada');
  const sel = items.find(i => i.id === selId) ?? null;
  const isToday = date === todayKey();

  const working = BARBERS.filter(b => isWorking(b, date));
  const capacity = h ? working.length * (h.close - h.open - (h.lunch ? h.lunch[1] - h.lunch[0] : 0)) : 0;
  const booked = active.reduce((s, i) => s + (i.end - i.start), 0);
  const income = active.filter(i => i.status !== 'no-show').reduce((s, i) => s + serviceById(i.serviceId).price, 0);
  const upcoming = active.filter(i => i.status === 'confirmada' && (!isToday || i.start >= now));
  const nextOne = upcoming[0];

  const move = (n: number) => { setDate(addDays(date, n)); setSelId(null); };
  const setStatus = (i: AgendaItem, s: Status, msg: string) => { store.setStatus(i.id, s); notify(msg); if (s === 'cancelada') setSelId(null); };

  return (
    <div className="mx-auto max-w-6xl px-4 pt-8 sm:px-6 lg:pt-10">
      <div className="flex flex-wrap items-end justify-between gap-4">
        <div>
          <p className="text-sm text-[#5E625F]">Panel del dueño</p>
          <h1 className="nv-serif mt-1 text-4xl sm:text-5xl">Agenda del día</h1>
        </div>
        <div className="flex items-center gap-2">
          <button onClick={() => move(-1)} aria-label="Día anterior" className="grid h-10 w-10 place-items-center rounded-full border border-[#CFCAC0] bg-white hover:border-[#17191B]"><ChevronLeft size={18} /></button>
          <div className="min-w-[180px] text-center">
            <p className="font-semibold">{relDay(date)}</p>
            {Math.abs(diffDays(date, todayKey())) <= 1 && <p className="text-xs text-[#5E625F]">{new Date(date + 'T12:00').toLocaleDateString('es-ES', { weekday: 'long', day: 'numeric', month: 'long' })}</p>}
          </div>
          <button onClick={() => move(1)} aria-label="Día siguiente" className="grid h-10 w-10 place-items-center rounded-full border border-[#CFCAC0] bg-white hover:border-[#17191B]"><ChevronRight size={18} /></button>
          {!isToday && <Btn variant="outline" className="px-4" onClick={() => { setDate(todayKey()); setSelId(null); }}>Hoy</Btn>}
        </div>
      </div>

      {!h ? (
        <div className="mt-8 rounded-3xl border-2 border-dashed border-[#CFCAC0] px-6 py-16 text-center">
          <CalendarX2 className="mx-auto text-[#8B8E8C]" size={32} />
          <p className="nv-serif mt-3 text-2xl">Domingo: la barbería está cerrada</p>
          <Btn className="mt-5" onClick={() => move(1)}>Ver el lunes</Btn>
        </div>
      ) : (
        <>
          <dl className="mt-6 grid grid-cols-2 gap-3 lg:grid-cols-4">
            <Kpi label="Citas" value={String(active.length)} sub={`${cancelled.length} canceladas`} />
            <Kpi label="Ingresos previstos" value={money(income)} sub="sin contar ausencias" />
            <Kpi label="Ocupación" value={`${Math.round((booked / Math.max(capacity, 1)) * 100)} %`} sub={`${working.length} barberos trabajando`} bar={booked / Math.max(capacity, 1)} />
            <Kpi label={isToday ? 'Siguiente cita' : 'Primera cita'} value={nextOne ? hhmm(nextOne.start) : '—'} sub={nextOne ? nextOne.client : 'Nada pendiente'} />
          </dl>

          <div className="mt-6 grid gap-6 lg:grid-cols-[1fr_320px]">
            <section className="min-w-0 overflow-hidden rounded-3xl bg-white">
              <div className="grid border-b border-[#E6E3DC]" style={{ gridTemplateColumns: `44px repeat(${BARBERS.length}, minmax(0,1fr))` }}>
                <span />
                {BARBERS.map(b => (
                  <div key={b.id} className="flex min-w-0 items-center gap-2 border-l border-[#E6E3DC] px-2 py-3 sm:px-3">
                    <Avatar src={b.photo} name={b.name} size={32} className="hidden sm:block" />
                    <div className="min-w-0">
                      <p className="truncate text-sm font-semibold">{b.short}</p>
                      <p className="truncate text-xs text-[#5E625F]">{isWorking(b, date) ? `${active.filter(i => i.barberId === b.id).length} citas` : 'Libra hoy'}</p>
                    </div>
                  </div>
                ))}
              </div>
              <div className="relative grid" style={{ gridTemplateColumns: `44px repeat(${BARBERS.length}, minmax(0,1fr))`, height: (h.close - h.open) * PX + 28 }}>
                <div className="relative">
                  {Array.from({ length: (h.close - h.open) / 60 + 1 }, (_, k) => (
                    <span key={k} className="nv-num absolute right-2 -translate-y-1/2 text-[11px] text-[#5E625F]" style={{ top: k * 60 * PX + 14 }}>{hhmm(h.open + k * 60).replace(':00', 'h')}</span>
                  ))}
                </div>
                {BARBERS.map(b => (
                  <div key={b.id} className={clsx('relative border-l border-[#E6E3DC]', !isWorking(b, date) && 'nv-busy')}>
                    {Array.from({ length: (h.close - h.open) / 30 }, (_, k) => (
                      <div key={k} className={clsx('absolute inset-x-0 border-t', k % 2 ? 'border-dashed border-[#F0EEEA]' : 'border-[#E6E3DC]')} style={{ top: k * 30 * PX + 14 }} />
                    ))}
                    {h.lunch && isWorking(b, date) && (
                      <div className="nv-lunch absolute inset-x-1 grid place-items-center rounded-lg text-xs text-[#5E625F]" style={{ top: (h.lunch[0] - h.open) * PX + 16, height: (h.lunch[1] - h.lunch[0]) * PX - 4 }}>Descanso</div>
                    )}
                    {active.filter(i => i.barberId === b.id).map(i => {
                      const short = i.end - i.start <= 30;
                      return (
                        <button
                          key={i.id}
                          onClick={() => setSelId(i.id)}
                          aria-label={`${hhmm(i.start)} ${i.client}, ${serviceById(i.serviceId).name}`}
                          className={clsx('absolute inset-x-1 overflow-hidden rounded-lg border-l-[3px] px-2 text-left transition-shadow hover:shadow-md', BLOCK[i.status], short ? 'py-1' : 'py-1.5', selId === i.id && 'ring-2 ring-[#B88A3E]', i.mine && 'shadow-[inset_0_0_0_1px_#C99A4A]')}
                          style={{ top: (i.start - h.open) * PX + 16, height: (i.end - i.start) * PX - 4 }}
                        >
                          <p className="truncate text-[12px] font-semibold leading-tight">{short ? `${hhmm(i.start)} ${i.client.split(' ')[0]}` : i.client}</p>
                          {!short && <p className="nv-num truncate text-[11px] leading-tight opacity-75">{hhmm(i.start)} · {serviceById(i.serviceId).name}</p>}
                        </button>
                      );
                    })}
                  </div>
                ))}
                {isToday && now > h.open && now < h.close && (
                  <div className="pointer-events-none absolute left-[38px] right-0 z-10 flex items-center" style={{ top: (now - h.open) * PX + 14 }}>
                    <span className="h-2.5 w-2.5 rounded-full bg-[#B23A32]" />
                    <span className="h-0.5 flex-1 bg-[#B23A32]" />
                  </div>
                )}
              </div>
            </section>

            <aside className="space-y-4 lg:sticky lg:top-24 lg:self-start">
              {sel ? (
                <div key={sel.id} className="nv-pop rounded-3xl bg-[#1E3A31] p-6 text-white">
                  <div className="flex items-start justify-between gap-3">
                    <div>
                      <p className="nv-num text-sm text-white/60">{hhmm(sel.start)} – {hhmm(sel.end)} · {sel.code}</p>
                      <h2 className="nv-serif mt-1 text-2xl">{sel.client}</h2>
                    </div>
                    <button onClick={() => setSelId(null)} aria-label="Cerrar ficha" className="rounded-full p-1.5 hover:bg-white/10"><X size={16} /></button>
                  </div>
                  <div className="mt-3"><StatusChip status={sel.status} /></div>
                  <dl className="mt-4 space-y-2 text-sm">
                    <div className="flex justify-between gap-3"><dt className="text-white/60">Servicio</dt><dd className="text-right font-semibold">{serviceById(sel.serviceId).name}</dd></div>
                    <div className="flex justify-between gap-3"><dt className="text-white/60">Barbero</dt><dd className="font-semibold">{barberById(sel.barberId).name}</dd></div>
                    <div className="flex justify-between gap-3"><dt className="text-white/60">Importe</dt><dd className="nv-num font-semibold">{money(serviceById(sel.serviceId).price)}</dd></div>
                    <div className="flex justify-between gap-3"><dt className="text-white/60">Teléfono</dt><dd className="nv-num font-semibold">{sel.phone}</dd></div>
                    <div className="flex justify-between gap-3"><dt className="text-white/60">Origen</dt><dd className="font-semibold capitalize">{sel.source}</dd></div>
                  </dl>
                  {sel.note && <p className="mt-4 flex gap-2 rounded-xl bg-white/10 p-3 text-sm"><MessageSquareText size={15} className="mt-0.5 shrink-0" /> {sel.note}</p>}
                  <div className="mt-5 grid gap-2">
                    {sel.status !== 'atendida' && <Btn variant="brass" onClick={() => setStatus(sel, 'atendida', `${sel.client.split(' ')[0]}: marcada como atendida.`)}><Check size={16} /> Marcar atendida</Btn>}
                    {sel.status !== 'no-show' && <Btn variant="outlineDark" onClick={() => setStatus(sel, 'no-show', 'Ausencia registrada.')}><UserX size={16} /> No se presentó</Btn>}
                    {sel.status !== 'confirmada' && <Btn variant="outlineDark" onClick={() => setStatus(sel, 'confirmada', 'Cita devuelta a pendiente.')}>Volver a pendiente</Btn>}
                    <Btn variant="ghost" className="text-[#F2B8B2] hover:bg-white/10" onClick={() => setStatus(sel, 'cancelada', 'Cita cancelada y hueco liberado.')}><Ban size={16} /> Cancelar cita</Btn>
                  </div>
                </div>
              ) : (
                <div className="rounded-3xl bg-white p-5">
                  <h2 className="nv-serif text-2xl">{isToday ? 'Lo que queda hoy' : 'Citas del día'}</h2>
                  {upcoming.length === 0 ? (
                    <p className="mt-3 text-sm text-[#5E625F]">No quedan citas pendientes.</p>
                  ) : (
                    <ul className="mt-3 divide-y divide-[#EFEEEA]">
                      {upcoming.slice(0, 6).map(i => {
                        const Icon = SOURCE_ICON[i.source];
                        return (
                          <li key={i.id}>
                            <button onClick={() => setSelId(i.id)} className="flex w-full items-center gap-3 rounded-lg py-2.5 text-left hover:bg-[#F7F6F2]">
                              <span className="nv-num w-12 shrink-0 text-sm font-semibold">{hhmm(i.start)}</span>
                              <span className="min-w-0 flex-1">
                                <span className="block truncate text-sm font-medium">{i.client}</span>
                                <span className="block truncate text-xs text-[#5E625F]">{serviceById(i.serviceId).name} · {barberById(i.barberId).short}</span>
                              </span>
                              <Icon size={14} className="shrink-0 text-[#8B8E8C]" aria-label={`Reservada por ${i.source}`} />
                            </button>
                          </li>
                        );
                      })}
                    </ul>
                  )}
                  {upcoming.length > 6 && <p className="mt-2 text-xs text-[#5E625F]">Y {upcoming.length - 6} más en la línea de tiempo.</p>}
                  <p className="mt-4 border-t border-[#EFEEEA] pt-3 text-xs text-[#5E625F]">Pulsa una cita para marcarla como atendida, registrar una ausencia o cancelarla.</p>
                </div>
              )}
              <div className="flex flex-wrap gap-x-4 gap-y-2 px-1 text-xs text-[#5E625F]">
                <Legend className="border-[#1E3A31] bg-[#E3ECE7]" label="Pendiente" />
                <Legend className="border-[#9A9C98] bg-[#ECEAE5]" label="Atendida" />
                <Legend className="border-[#B23A32] bg-[#F6E1DE]" label="No asistió" />
                <span className="flex items-center gap-1.5"><span className="h-3 w-3 rounded-sm shadow-[inset_0_0_0_1px_#C99A4A]" /> Tus reservas</span>
              </div>
            </aside>
          </div>
        </>
      )}
    </div>
  );
}

function Kpi({ label, value, sub, bar }: { label: string; value: string; sub: string; bar?: number }) {
  return (
    <div className="rounded-2xl bg-white p-4">
      <dt className="text-sm text-[#5E625F]">{label}</dt>
      <dd className="nv-serif nv-num mt-1 truncate text-3xl">{value}</dd>
      {bar !== undefined ? (
        <div className="mt-2 h-1.5 overflow-hidden rounded-full bg-[#EFEEEA]"><div className="h-full rounded-full bg-[#B88A3E] transition-all duration-500" style={{ width: `${Math.min(100, bar * 100)}%` }} /></div>
      ) : (
        <dd className="mt-1 truncate text-xs text-[#5E625F]">{sub}</dd>
      )}
    </div>
  );
}

function Legend({ className, label }: { className: string; label: string }) {
  return <span className="flex items-center gap-1.5"><span className={clsx('h-3 w-3 rounded-sm border-l-[3px]', className)} /> {label}</span>;
}

import { useState, type ReactNode } from 'react';
import clsx from 'clsx';
import confetti from 'canvas-confetti';
import { ArrowLeft, CalendarDays, Check, CircleCheckBig, Clock, Scissors, User } from 'lucide-react';
import type { Appointment, Draft, Route } from '../lib/types';
import type { Store } from '../lib/store';
import { newCode } from '../lib/store';
import { barberById, serviceById } from '../data/catalog';
import { dayItems, isFree, pickBarber } from '../lib/schedule';
import { duration, hhmm, money, relDay } from '../lib/dates';
import { StepBarber, StepDetails, StepService, StepTime, validate, type Form, type FormErrors } from './BookingSteps';
import { Avatar, Btn } from './ui';

type Props = { store: Store; draft: Draft; setDraft: (d: Draft) => void; go: (r: Route) => void; notify: (m: string) => void };

const STEPS = ['Servicio', 'Barbero', 'Día y hora', 'Tus datos'];
const TITLES = ['¿Qué te hacemos hoy?', '¿Con quién?', '¿Cuándo te viene bien?', 'Último paso: tus datos'];

export default function Booking({ store, draft, setDraft, go, notify }: Props) {
  const p = store.profile;
  const [form, setForm] = useState<Form>({ name: p?.name ?? '', phone: p?.phone ?? '', email: p?.email ?? '', note: '', reminder: true });
  const [errors, setErrors] = useState<FormErrors>({});
  const [doneId, setDoneId] = useState<string | null>(null);

  const svc = draft.serviceId ? serviceById(draft.serviceId) : null;
  const resched = draft.rescheduleId ? store.appts.find(a => a.id === draft.rescheduleId) ?? null : null;
  const set = (patch: Partial<Draft>) => setDraft({ ...draft, ...patch });
  const minStep = resched ? 2 : 0;

  const can = [!!draft.serviceId, !!draft.barberId, draft.date !== null && draft.start !== null, true];
  const hint = ['Elige un servicio para continuar.', 'Elige barbero o «Cualquiera disponible».', 'Elige un día y una hora libres.', ''];
  const last = draft.step === 3 || (resched && draft.step === 2);

  const confirm = () => {
    if (!svc || !draft.barberId || draft.date === null || draft.start === null) return;
    const items = dayItems(draft.date, store.appts, store.overrides, resched?.id);
    const barberId = draft.barberId === 'any' ? pickBarber(draft.date, draft.start, svc.minutes, items) : draft.barberId;
    if (!barberId || !isFree(draft.date, barberId, draft.start, svc.minutes, items)) {
      notify('Esa hora se acaba de ocupar. Elige otra, por favor.');
      setDraft({ ...draft, step: 2, start: null });
      return;
    }
    if (resched) {
      store.reschedule(resched.id, { date: draft.date, start: draft.start, barberId });
      setDoneId(resched.id);
    } else {
      const e = validate(form);
      setErrors(e);
      if (Object.keys(e).length) return;
      const a: Appointment = {
        id: `w${Date.now()}`, code: newCode(), serviceId: svc.id, barberId, date: draft.date, start: draft.start,
        client: form.name.trim(), phone: form.phone.trim(), email: form.email.trim() || undefined, note: form.note.trim() || undefined,
        status: 'confirmada', mine: true, source: 'web', createdAt: Date.now(),
      };
      store.book(a, { name: a.client, phone: a.phone, email: form.email.trim() });
      setDoneId(a.id);
    }
    confetti({ particleCount: 60, spread: 70, ticks: 110, origin: { y: 0.3 }, colors: ['#B23A32', '#F4F1EA', '#1E3A31', '#C99A4A'] });
    window.scrollTo({ top: 0 });
  };

  const next = () => (last ? confirm() : can[draft.step] && set({ step: draft.step + 1 }));
  const back = () => (draft.step > minStep ? set({ step: draft.step - 1 }) : go(resched ? 'mis-citas' : 'inicio'));

  const done = doneId ? store.appts.find(a => a.id === doneId) : null;
  if (done) return <Success appt={done} rescheduled={!!resched} go={go} onAgain={() => { setDoneId(null); setDraft({ step: 0, serviceId: null, barberId: null, date: null, start: null, rescheduleId: null }); }} />;

  const actionLabel = last ? (resched ? 'Guardar nueva hora' : 'Confirmar reserva') : 'Continuar';
  const nav = (
    <div className="flex items-center gap-3">
      <Btn variant="ghost" onClick={back} className="px-3"><ArrowLeft size={16} /> {draft.step > minStep ? 'Atrás' : 'Salir'}</Btn>
      <Btn variant="green" className="flex-1 py-3" disabled={!can[draft.step]} onClick={next}>{actionLabel}</Btn>
    </div>
  );

  return (
    <div className="mx-auto max-w-6xl px-4 pt-8 sm:px-6 lg:pt-10">
      {resched && (
        <p className="mb-4 rounded-xl bg-[#F3E9D6] px-4 py-3 text-sm text-[#5C4318]">
          Estás cambiando la hora de tu cita {resched.code}. La hora actual se libera al guardar.
        </p>
      )}
      <ol className="flex gap-2" aria-label="Pasos de la reserva">
        {STEPS.map((s, i) => (
          <li key={s} className="flex-1">
            <button
              disabled={i > draft.step || i < minStep}
              onClick={() => set({ step: i })}
              className="w-full text-left disabled:cursor-default"
              aria-current={i === draft.step ? 'step' : undefined}
            >
              <span className={clsx('block h-1.5 rounded-full', i <= draft.step ? 'bg-[#1E3A31]' : 'bg-[#D9D5CC]')} />
              <span className={clsx('mt-2 hidden items-center gap-1.5 text-sm sm:flex', i === draft.step ? 'font-semibold text-[#17191B]' : 'text-[#5E625F]')}>
                {i < draft.step && <Check size={14} />} {s}
              </span>
            </button>
          </li>
        ))}
      </ol>
      <p className="mt-3 text-sm text-[#5E625F] sm:hidden">Paso {draft.step + 1} de 4 · {STEPS[draft.step]}</p>

      <div className="mt-6 grid gap-8 lg:grid-cols-[1fr_340px]">
        <section key={draft.step} className="nv-in min-w-0">
          <h1 className="nv-serif mb-6 text-4xl sm:text-[44px]">{TITLES[draft.step]}</h1>
          {draft.step === 0 && <StepService value={draft.serviceId} onPick={id => set({ serviceId: id, start: null })} />}
          {draft.step === 1 && <StepBarber value={draft.barberId} onPick={id => set({ barberId: id, start: null })} />}
          {draft.step === 2 && svc && draft.barberId && (
            <StepTime
              store={store} barberId={draft.barberId} minutes={svc.minutes} date={draft.date} start={draft.start} excludeId={resched?.id ?? null}
              onDate={d => setDraft({ ...draft, date: d, start: d === draft.date ? draft.start : null })}
              onStart={(m, d) => set({ start: m, date: d ?? draft.date })}
            />
          )}
          {draft.step === 3 && <StepDetails form={form} setForm={setForm} errors={errors} />}
          <div className="mt-6 lg:hidden">
            {nav}
            {!can[draft.step] && <p className="mt-2 text-center text-sm text-[#5E625F]">{hint[draft.step]}</p>}
          </div>
        </section>

        <aside className="lg:sticky lg:top-24 lg:self-start">
          <div className="rounded-3xl bg-[#1E3A31] p-6 text-white">
            <h2 className="nv-serif text-2xl">Tu cita</h2>
            <dl className="mt-4 space-y-4 text-sm">
              <Row icon={<Scissors size={16} />} label="Servicio" value={svc ? `${svc.name} · ${duration(svc.minutes)}` : null} />
              <Row
                icon={draft.barberId && draft.barberId !== 'any' ? <Avatar src={barberById(draft.barberId).photo} name={barberById(draft.barberId).name} size={24} /> : <User size={16} />}
                label="Barbero"
                value={draft.barberId ? (draft.barberId === 'any' ? 'Cualquiera disponible' : barberById(draft.barberId).name) : null}
              />
              <Row icon={<CalendarDays size={16} />} label="Día" value={draft.date ? relDay(draft.date) : null} />
              <Row icon={<Clock size={16} />} label="Hora" value={draft.start !== null && svc ? `${hhmm(draft.start)} – ${hhmm(draft.start + svc.minutes)}` : null} />
            </dl>
            <div className="mt-5 flex items-baseline justify-between border-t border-white/15 pt-4">
              <span className="text-white/70">Total en el local</span>
              <span className="nv-serif nv-num text-3xl">{svc ? money(svc.price) : '—'}</span>
            </div>
            <div className="mt-5 hidden lg:block">
              <Btn variant="brass" className="w-full py-3 text-[15px]" disabled={!can[draft.step]} onClick={next}>{actionLabel}</Btn>
              <p className="mt-2 min-h-[20px] text-center text-sm text-white/60">{can[draft.step] ? 'Cancelación gratis hasta 2 h antes.' : hint[draft.step]}</p>
            </div>
          </div>
          {draft.step > minStep && (
            <button onClick={back} className="mt-3 hidden w-full items-center justify-center gap-1.5 py-2 text-sm text-[#5E625F] hover:text-[#17191B] lg:flex"><ArrowLeft size={15} /> Volver al paso anterior</button>
          )}
        </aside>
      </div>
    </div>
  );
}

function Row({ icon, label, value }: { icon: ReactNode; label: string; value: string | null }) {
