type TimeProps = {
  store: Store;
  barberId: string;
  minutes: number;
  date: string | null;
  start: number | null;
  excludeId: string | null;
  onDate: (d: string) => void;
  onStart: (m: number, d?: string) => void;
};

export function StepTime({ store, barberId, minutes, date, start, excludeId, onDate, onStart }: TimeProps) {
  const days = useMemo(() => {
    return Array.from({ length: 14 }, (_, i) => {
      const d = addDays(todayKey(), i);
      const items = dayItems(d, store.appts, store.overrides, excludeId ?? undefined);
      const slots = slotOptions(d, barberId, minutes, items);
      const working = !!hoursFor(d) && (barberId === 'any' || isWorking(BARBERS.find(b => b.id === barberId)!, d));
      return { d, slots, working, free: slots.filter(s => s.free).length };
    });
  }, [store.appts, store.overrides, barberId, minutes, excludeId]);

  const sel = days.find(x => x.d === date) ?? null;
  const firstFree = () => {
    for (const x of days) {
      const s = x.slots.find(o => o.free);
      if (s) { onStart(s.start, x.d); return; }
    }
  };
  const morning = sel?.slots.filter(s => s.start < 14 * 60) ?? [];
  const afternoon = sel?.slots.filter(s => s.start >= 14 * 60) ?? [];

  return (
    <div className="space-y-6">
      <div className="flex flex-wrap items-center justify-between gap-3">
        <p className="text-sm text-[#5E625F]">Próximas dos semanas · los huecos rayados ya están reservados.</p>
        <button onClick={firstFree} className="inline-flex items-center gap-1.5 rounded-full bg-[#F3E9D6] px-4 py-2 text-sm font-semibold text-[#5C4318] hover:bg-[#EBDDC2]">
          <Zap size={15} /> Primera hora libre
        </button>
      </div>

      <div className="nv-scroll -mx-4 flex gap-2 overflow-x-auto px-4 pb-1 sm:mx-0 sm:px-0">
        {days.map(x => {
          const active = x.d === date;
          const disabled = !x.working || x.free === 0;
          return (
            <button
              key={x.d}
              disabled={disabled}
              onClick={() => onDate(x.d)}
              aria-pressed={active}
              aria-label={`${relDay(x.d)}: ${x.working ? `${x.free} horas libres` : 'cerrado'}`}
              className={clsx(
                'flex w-[68px] shrink-0 flex-col items-center rounded-2xl border-2 py-2.5 transition-colors',
                active ? 'border-[#1E3A31] bg-[#1E3A31] text-white' : 'border-transparent bg-white hover:border-[#CFCAC0]',
                disabled && 'cursor-not-allowed bg-transparent opacity-50 hover:border-transparent',
              )}
            >
              <span className={clsx('text-xs capitalize', active ? 'text-white/70' : 'text-[#5E625F]')}>{x.d === todayKey() ? 'hoy' : weekdayShort(x.d)}</span>
              <span className="nv-serif nv-num text-2xl leading-tight">{dayNum(x.d)}</span>
              <span className={clsx('text-[11px]', active ? 'text-[#E6C886]' : 'text-[#5E625F]')}>{!x.working ? 'Cerrado' : x.free ? `${x.free} ${x.free === 1 ? 'libre' : 'libres'}` : 'Completo'}</span>
            </button>
          );
        })}
      </div>

      {!sel ? (
        <div className="rounded-2xl border-2 border-dashed border-[#CFCAC0] p-8 text-center text-[#5E625F]">
          Elige un día para ver las horas, o pulsa «Primera hora libre».
        </div>
      ) : (
        <div className="rounded-2xl bg-white p-4 sm:p-6">
          <h3 className="nv-serif text-xl">{relDay(sel.d)}{sel.d === todayKey() || addDays(todayKey(), 1) === sel.d ? `, ${dayNum(sel.d)} ${monthShort(sel.d)}` : ''}</h3>
          {[['Mañana', morning], ['Tarde', afternoon]].map(([label, list]) =>
            (list as typeof morning).length ? (
              <div key={label as string} className="mt-4">
                <p className="mb-2 text-sm font-medium text-[#5E625F]">{label as string}</p>
                <div className="grid grid-cols-4 gap-2 sm:grid-cols-6 lg:grid-cols-7">
                  {(list as typeof morning).map(s => (
                    <button
                      key={s.start}
                      disabled={!s.free}
                      onClick={() => onStart(s.start)}
                      aria-pressed={start === s.start}
                      aria-label={`${hhmm(s.start)}${s.free ? '' : ', ocupado'}`}
                      className={clsx(
                        'nv-num rounded-xl py-2.5 text-sm font-semibold transition-colors',
                        !s.free && 'nv-busy cursor-not-allowed text-[#8B8E8C] line-through',
                        s.free && start !== s.start && 'border border-[#CFCAC0] hover:border-[#1E3A31]',
                        start === s.start && 'bg-[#1E3A31] text-white',
                      )}
                    >
                      {hhmm(s.start)}
                    </button>
                  ))}
                </div>
              </div>
            ) : null,
          )}
          {!sel.slots.length && <p className="mt-3 text-sm text-[#5E625F]">Hoy ya no quedan horas para este servicio.</p>}
          <p className="mt-5 flex items-center gap-2 text-xs text-[#5E625F]"><Sparkles size={13} /> Termina a las {start !== null ? hhmm(start + minutes) : '—'} · duración {duration(minutes)}</p>
        </div>
      )}
    </div>
  );
}

export type Form = { name: string; phone: string; email: string; note: string; reminder: boolean };
export type FormErrors = Partial<Record<'name' | 'phone' | 'email', string>>;

export function validate(f: Form): FormErrors {
  const e: FormErrors = {};
  if (f.name.trim().length < 3) e.name = 'Escribe tu nombre y apellido.';
  const digits = f.phone.replace(/\D/g, '');
  if (!/^[679]\d{8}$/.test(digits)) e.phone = 'Introduce un teléfono español de 9 cifras.';
  if (f.email.trim() && !/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(f.email.trim())) e.email = 'Revisa el correo: falta algo.';
  return e;
}

const input = 'mt-1.5 w-full rounded-xl border bg-white px-4 py-3 text-[15px] outline-none transition-colors focus:border-[#1E3A31] focus:ring-2 focus:ring-[#1E3A31]/15';

export function StepDetails({ form, setForm, errors }: { form: Form; setForm: (f: Form) => void; errors: FormErrors }) {
  const field = (k: 'name' | 'phone' | 'email', label: string, props: Record<string, string>) => (
    <label className="block">
      <span className="text-sm font-semibold">{label}</span>
      <input
        value={form[k]}
        onChange={e => setForm({ ...form, [k]: e.target.value })}
        aria-invalid={!!errors[k]}
        className={clsx(input, errors[k] ? 'border-[#B23A32]' : 'border-[#CFCAC0]')}
        {...props}
      />
      {errors[k] && <span className="mt-1 block text-sm text-[#9C322B]">{errors[k]}</span>}
    </label>
  );
  return (
    <div className="space-y-5 rounded-2xl bg-white p-5 sm:p-6">
      {field('name', 'Nombre y apellido', { autoComplete: 'name', placeholder: 'Ej.: Daniel Ortega' })}
      <div className="grid gap-5 sm:grid-cols-2">
        {field('phone', 'Teléfono', { autoComplete: 'tel', inputMode: 'tel', placeholder: '612 345 678' })}
        {field('email', 'Correo (opcional)', { autoComplete: 'email', type: 'email', placeholder: 'tu@correo.es' })}
      </div>
      <label className="block">
        <span className="text-sm font-semibold">Nota para el barbero (opcional)</span>
        <textarea
          rows={3}
          value={form.note}
          onChange={e => setForm({ ...form, note: e.target.value })}
          placeholder="Ej.: Degradado bajo, dejar volumen arriba."
          className={clsx(input, 'resize-none border-[#CFCAC0]')}
        />
      </label>
      <label className="flex cursor-pointer items-center gap-3 text-sm">
        <input type="checkbox" checked={form.reminder} onChange={e => setForm({ ...form, reminder: e.target.checked })} className="h-4 w-4 accent-[#1E3A31]" />
        Recordármelo por SMS el día antes
      </label>
    </div>
  );
}

import { useState } from 'react';
import clsx from 'clsx';
import { CalendarPlus, Clock, MessageSquareText, Repeat2, RotateCcw } from 'lucide-react';
import type { Appointment, Draft } from '../lib/types';
import type { Store } from '../lib/store';
import { barberById, serviceById } from '../data/catalog';
import { dayNum, diffDays, duration, hhmm, money, monthShort, nowMinutes, relDay, todayKey, weekdayShort } from '../lib/dates';
import { Avatar, Btn, Confirm, StatusChip } from './ui';

type Props = { store: Store; onBook: (d?: Partial<Draft>) => void; notify: (m: string) => void };
type Tab = 'proximas' | 'historial';

const isUpcoming = (a: Appointment) => a.status === 'confirmada' && (a.date > todayKey() || (a.date === todayKey() && a.start > nowMinutes()));
/** Se puede cancelar o cambiar hasta 2 horas antes. */
const editable = (a: Appointment) => diffDays(a.date, todayKey()) * 1440 + a.start - nowMinutes() > 120;

export default function MyAppointments({ store, onBook, notify }: Props) {
  const [tab, setTab] = useState<Tab>('proximas');
  const [cancelId, setCancelId] = useState<string | null>(null);
  const [confirmReset, setConfirmReset] = useState(false);

  const mine = store.appts.filter(a => a.mine);
  const upcoming = mine.filter(isUpcoming).sort((a, b) => a.date.localeCompare(b.date) || a.start - b.start);
  const history = mine.filter(a => !isUpcoming(a)).sort((a, b) => b.date.localeCompare(a.date) || b.start - a.start);
  const list = tab === 'proximas' ? upcoming : history;
  const visits = mine.filter(a => a.status === 'atendida');
  const lastVisit = visits.sort((a, b) => b.date.localeCompare(a.date))[0];
  const spent = visits.reduce((s, a) => s + serviceById(a.serviceId).price, 0);
  const toCancel = mine.find(a => a.id === cancelId);

  return (
    <div className="mx-auto max-w-6xl px-4 pt-8 sm:px-6 lg:pt-10">
      <div className="flex flex-wrap items-end justify-between gap-4">
        <div>
          <h1 className="nv-serif text-4xl sm:text-5xl">Mis citas</h1>
          <p className="mt-2 text-[#5E625F]">Consulta, cambia la hora o cancela gratis hasta 2 horas antes.</p>
        </div>
        <Btn onClick={() => onBook()}><CalendarPlus size={16} /> Nueva cita</Btn>
      </div>

      <div className="mt-8 grid gap-8 lg:grid-cols-[1fr_320px]">
        <section className="min-w-0">
          <div role="tablist" className="inline-flex rounded-full bg-[#E2DFD8] p-1">
            {([['proximas', `Próximas (${upcoming.length})`], ['historial', `Historial (${history.length})`]] as const).map(([id, label]) => (
              <button
                key={id}
                role="tab"
                aria-selected={tab === id}
                onClick={() => setTab(id)}
                className={clsx('rounded-full px-5 py-2 text-sm font-semibold transition-colors', tab === id ? 'bg-white text-[#17191B] shadow-sm' : 'text-[#55595C] hover:text-[#17191B]')}
              >
                {label}
              </button>
            ))}
          </div>

          {list.length === 0 ? (
            <div className="mt-5 rounded-3xl border-2 border-dashed border-[#CFCAC0] px-6 py-12 text-center">
              <p className="nv-serif text-2xl">{tab === 'proximas' ? 'No tienes citas pendientes' : 'Aún no hay historial'}</p>
              <p className="mt-2 text-[#5E625F]">Reserva en un minuto y aparecerá aquí.</p>
              <Btn className="mt-5" onClick={() => onBook()}>Reservar cita</Btn>
            </div>
          ) : (
            <ul className="mt-5 space-y-3">
              {list.map(a => {
                const s = serviceById(a.serviceId), b = barberById(a.barberId);
                const past = tab === 'historial';
                return (
