                        </div>
                        <p className="mt-1 flex flex-wrap items-center gap-x-3 gap-y-1 text-sm text-[#5E625F]">
                          <span className="nv-num flex items-center gap-1"><Clock size={14} /> {Math.abs(diffDays(a.date, todayKey())) <= 1 ? `${relDay(a.date)}, ` : ''}{hhmm(a.start)} · {duration(s.minutes)}</span>
                          <span className="flex items-center gap-1.5"><Avatar src={b.photo} name={b.name} size={20} /> {b.short}</span>
                          <span className="nv-num font-semibold text-[#17191B]">{money(s.price)}</span>
                        </p>
                        {a.note && <p className="mt-1.5 flex items-start gap-1.5 text-sm text-[#5E625F]"><MessageSquareText size={14} className="mt-0.5 shrink-0" /> {a.note}</p>}
                      </div>
                    </div>
                    <div className="flex shrink-0 gap-2">
                      {past ? (
                        <Btn variant="outline" className="flex-1 px-4" onClick={() => onBook({ serviceId: a.serviceId, barberId: a.barberId })}>
                          <Repeat2 size={15} /> Repetir
                        </Btn>
                      ) : editable(a) ? (
                        <>
                          <Btn variant="outline" className="flex-1 px-4" onClick={() => onBook({ serviceId: a.serviceId, barberId: a.barberId, date: a.date, start: null, step: 2, rescheduleId: a.id })}>Cambiar hora</Btn>
                          <Btn variant="ghost" className="flex-1 px-4 text-[#9C322B] hover:bg-[#F6E1DE]" onClick={() => setCancelId(a.id)}>Cancelar cita</Btn>
                        </>
                      ) : (
                        <p className="text-sm text-[#5E625F]">Faltan menos de 2 h: llámanos para cambiarla.</p>
                      )}
                    </div>
                  </li>
                );
              })}
            </ul>
          )}
        </section>

        <aside className="space-y-4">
          <div className="rounded-3xl bg-white p-6">
            <h2 className="nv-serif text-2xl">Tus datos</h2>
            {store.profile ? (
              <dl className="mt-3 space-y-1 text-sm">
                <dd className="font-semibold">{store.profile.name}</dd>
                <dd className="nv-num text-[#5E625F]">{store.profile.phone}</dd>
                {store.profile.email && <dd className="text-[#5E625F]">{store.profile.email}</dd>}
              </dl>
            ) : (
              <p className="mt-2 text-sm text-[#5E625F]">Se guardan al hacer tu primera reserva.</p>
            )}
            <div className="mt-5 grid grid-cols-2 gap-3 border-t border-[#E6E3DC] pt-5">
              <div><p className="nv-serif nv-num text-3xl">{visits.length}</p><p className="text-sm text-[#5E625F]">visitas</p></div>
              <div><p className="nv-serif nv-num text-3xl">{money(spent)}</p><p className="text-sm text-[#5E625F]">en servicios</p></div>
            </div>
            {lastVisit && (
              <Btn variant="outline" className="mt-5 w-full" onClick={() => onBook({ serviceId: lastVisit.serviceId, barberId: lastVisit.barberId })}>
                <Repeat2 size={15} /> Repetir última visita
              </Btn>
            )}
          </div>
          <button onClick={() => setConfirmReset(true)} className="flex items-center gap-2 px-2 text-sm text-[#5E625F] hover:text-[#17191B]">
            <RotateCcw size={14} /> Restablecer datos de ejemplo
          </button>
        </aside>
      </div>

      {toCancel && (
        <Confirm
          title="¿Cancelar esta cita?"
          body={<>Se liberará la hora de <b>{serviceById(toCancel.serviceId).name}</b> con {barberById(toCancel.barberId).short}, {relDay(toCancel.date).toLowerCase()} a las {hhmm(toCancel.start)}.</>}
          confirm="Sí, cancelar"
          cancel="No, mantenerla"
          onClose={() => setCancelId(null)}
          onConfirm={() => { store.setStatus(toCancel.id, 'cancelada'); setCancelId(null); notify(`Cita ${toCancel.code} cancelada. La hora queda libre.`); }}
        />
      )}
      {confirmReset && (
        <Confirm
          title="¿Restablecer los datos?"
          body="Se borrarán tus reservas y cambios, y volverán las citas de ejemplo."
          confirm="Restablecer"
          cancel="Volver"
          onClose={() => setConfirmReset(false)}
          onConfirm={() => { store.reset(); setConfirmReset(false); notify('Datos de ejemplo restablecidos.'); }}
        />
      )}
    </div>
  );
}

