type BtnProps = {
  children: ReactNode;
  onClick?: () => void;
  variant?: 'brass' | 'green' | 'ghost' | 'outline' | 'outlineDark' | 'danger';
  className?: string;
  disabled?: boolean;
  type?: 'button' | 'submit';
};

const VARIANT = {
  brass: 'bg-[#C99A4A] text-[#17191B] hover:bg-[#D6A956]',
  green: 'bg-[#1E3A31] text-white hover:bg-[#28493E]',
  ghost: 'text-[#17191B] hover:bg-black/5',
  outline: 'border border-[#CFCAC0] bg-white text-[#17191B] hover:border-[#17191B]',
  outlineDark: 'border border-white/30 text-white hover:border-white hover:bg-white/5',
  danger: 'bg-[#B23A32] text-white hover:bg-[#9C322B]',
};

export function Btn({ children, onClick, variant = 'green', className, disabled, type = 'button' }: BtnProps) {
  return (
    <button
      type={type}
      onClick={onClick}
      disabled={disabled}
      className={clsx(
        'inline-flex items-center justify-center gap-2 whitespace-nowrap rounded-full px-5 py-2.5 text-sm font-semibold transition-colors disabled:cursor-not-allowed disabled:opacity-45',
        VARIANT[variant],
        className,
      )}
    >
      {children}
    </button>
