}

export function Toast({ message, onClose }: { message: string; onClose: () => void }) {
  useEffect(() => {
    const t = setTimeout(onClose, 3800);
    return () => clearTimeout(t);
  }, [message, onClose]);
  return (
    <div role="status" className="nv-toast fixed bottom-16 left-1/2 z-50 flex max-w-[calc(100%-32px)] items-center gap-3 rounded-full bg-[#17191B] py-2.5 pl-5 pr-2 text-sm text-white shadow-xl">
      <span>{message}</span>
      <button onClick={onClose} aria-label="Cerrar aviso" className="rounded-full p-1.5 hover:bg-white/10">
        <X size={14} />
      </button>
    </div>
  );
}

type ConfirmProps = { title: string; body: ReactNode; confirm: string; cancel: string; onConfirm: () => void; onClose: () => void };

export function Confirm({ title, body, confirm, cancel, onConfirm, onClose }: ConfirmProps) {
  useEffect(() => {
    const k = (e: KeyboardEvent) => e.key === 'Escape' && onClose();
    window.addEventListener('keydown', k);
    return () => window.removeEventListener('keydown', k);
  }, [onClose]);
  return (
    <div className="fixed inset-0 z-50 flex items-end justify-center bg-[#17191B]/55 p-4 sm:items-center" onClick={onClose}>
      <div role="dialog" aria-modal="true" aria-label={title} onClick={e => e.stopPropagation()} className="nv-pop w-full max-w-md rounded-2xl bg-white p-6 shadow-2xl">
        <h2 className="nv-serif text-2xl text-[#17191B]">{title}</h2>
        <div className="mt-2 text-sm leading-relaxed text-[#55595C]">{body}</div>
        <div className="mt-6 flex flex-col-reverse gap-2 sm:flex-row sm:justify-end">
          <Btn variant="outline" onClick={onClose}>{cancel}</Btn>
          <Btn variant="danger" onClick={onConfirm}>{confirm}</Btn>
        </div>
      </div>
    </div>
  );
}

