export const pad = (n: number) => String(n).padStart(2, '0');

export function toKey(d: Date) {
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
}

export function fromKey(k: string) {
  const [y, m, d] = k.split('-').map(Number);
  return new Date(y, m - 1, d);
}

export const todayKey = () => toKey(new Date());

export function addDays(k: string, n: number) {
  const d = fromKey(k);
  d.setDate(d.getDate() + n);
  return toKey(d);
}

export function diffDays(a: string, b: string) {
  return Math.round((fromKey(a).getTime() - fromKey(b).getTime()) / 86400000);
}

export const nowMinutes = () => {
  const d = new Date();
  return d.getHours() * 60 + d.getMinutes();
};

export const hhmm = (m: number) => `${pad(Math.floor(m / 60))}:${pad(m % 60)}`;

const WD = ['dom', 'lun', 'mar', 'mié', 'jue', 'vie', 'sáb'];
const MO = ['ene', 'feb', 'mar', 'abr', 'may', 'jun', 'jul', 'ago', 'sept', 'oct', 'nov', 'dic'];
const MO_LONG = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'];
const WD_LONG = ['domingo', 'lunes', 'martes', 'miércoles', 'jueves', 'viernes', 'sábado'];

export const weekday = (k: string) => fromKey(k).getDay();
export const weekdayShort = (k: string) => WD[weekday(k)];
export const monthShort = (k: string) => MO[fromKey(k).getMonth()];
export const dayNum = (k: string) => fromKey(k).getDate();

const cap = (s: string) => s.charAt(0).toUpperCase() + s.slice(1);

export function longDate(k: string) {
  const d = fromKey(k);
  return `${WD_LONG[d.getDay()]}, ${d.getDate()} de ${MO_LONG[d.getMonth()]}`;
}

/** «Hoy», «Mañana», «Ayer» o «Jueves, 16 de octubre». */
export function relDay(k: string) {
  const d = diffDays(k, todayKey());
  if (d === 0) return 'Hoy';
  if (d === 1) return 'Mañana';
  if (d === -1) return 'Ayer';
  return cap(longDate(k));
}

export function money(n: number) {
  return `${n.toLocaleString('es-ES', { minimumFractionDigits: n % 1 ? 2 : 0, maximumFractionDigits: 2 })} €`;
}

export const duration = (m: number) => (m < 60 ? `${m} min` : m % 60 ? `${Math.floor(m / 60)} h ${m % 60} min` : `${m / 60} h`);

import type { AgendaItem, Appointment, Barber, Status } from './types';
import { BARBERS, CLIENTS, SERVICES, serviceById } from '../data/catalog';
import { diffDays, nowMinutes, todayKey, weekday } from './dates';

export type Hours = { open: number; close: number; lunch?: [number, number] };
export type Overrides = Record<string, Status>;
export type SlotOption = { start: number; free: boolean };

/** Horario de la barbería según el día de la semana. */
export function hoursFor(date: string): Hours | null {
  const wd = weekday(date);
  if (wd === 0) return null;
  if (wd === 6) return { open: 9 * 60, close: 15 * 60 };
  return { open: 10 * 60, close: 20 * 60, lunch: [14 * 60, 15 * 60] };
}

export const isWorking = (b: Barber, date: string) => !!hoursFor(date) && !b.offDays.includes(weekday(date));

// ---------- Generador pseudoaleatorio con semilla (misma agenda cada vez) ----------
function hash(s: string) {
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
  return h >>> 0;
}
function mulberry32(seed: number) {
  let a = seed;
  return () => {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const slotLen = (min: number) => Math.ceil(min / 30) * 30;
const overlaps = (a: number, b: number, c: number, d: number) => a < d && c < b;

/** Citas «de la casa» para un barbero y un día. Dependen solo del desplazamiento respecto a hoy. */
function generated(date: string, barber: Barber): AgendaItem[] {
  const h = hoursFor(date);
  if (!h || !isWorking(barber, date)) return [];
  const off = diffDays(date, todayKey());
  const rng = mulberry32(hash(`navaja:${off}:${barber.id}`));
  const sat = weekday(date) === 6;
  const density = (off <= 0 ? 0.62 : off <= 2 ? 0.55 : off <= 6 ? 0.42 : 0.3) + (sat ? 0.15 : 0);
  const now = nowMinutes();
  const out: AgendaItem[] = [];
  let t = h.open;
  while (t + 30 <= h.close) {
    if (h.lunch && t >= h.lunch[0] && t < h.lunch[1]) { t = h.lunch[1]; continue; }
    const roll = rng(), pick = rng(), who = rng(), fate = rng(), src = rng();
    if (roll >= density) { t += 30; continue; }
    const fits = (min: number) => t + min <= h.close && !(h.lunch && overlaps(t, t + min, h.lunch[0], h.lunch[1]));
    let svc = SERVICES[Math.floor(pick * SERVICES.length)];
    if (!fits(svc.minutes)) svc = SERVICES[0];
    if (!fits(svc.minutes)) { t += 30; continue; }
    const end = t + svc.minutes;
    const past = off < 0 || (off === 0 && end <= now);
    const client = CLIENTS[Math.floor(who * CLIENTS.length)];
    out.push({
      id: `g-${date}-${barber.id}-${t}`, code: `NV-${1000 + Math.floor(fate * 8999)}`, serviceId: svc.id, barberId: barber.id,
      date, start: t, end, client, phone: `6${String(Math.floor(who * 1e8)).padStart(8, '0')}`.replace(/(\d{3})(\d{3})(\d{3})/, '$1 $2 $3'),
      status: past ? (fate < 0.06 ? 'no-show' : 'atendida') : 'confirmada', mine: false,
      source: src < 0.55 ? 'web' : src < 0.85 ? 'teléfono' : 'en local', createdAt: 0, generated: true,
    });
    t += slotLen(svc.minutes);
  }
  return out;
}

const withEnd = (a: Appointment): AgendaItem => ({ ...a, end: a.start + serviceById(a.serviceId).minutes, generated: false });

/** Todas las citas del día (incluidas canceladas), con los cambios de estado del dueño aplicados. */
export function dayItems(date: string, appts: Appointment[], overrides: Overrides, excludeId?: string): AgendaItem[] {
  const stored = appts.filter(a => a.date === date && a.id !== excludeId).map(withEnd);
  const active = stored.filter(a => a.status !== 'cancelada');
  const gen = BARBERS.flatMap(b => generated(date, b))
    .filter(g => !active.some(s => s.barberId === g.barberId && overlaps(g.start, g.end, s.start, s.end)))
    .map(g => (overrides[g.id] ? { ...g, status: overrides[g.id] } : g));
  return [...stored, ...gen].sort((a, b) => a.start - b.start);
}

function busy(date: string, barberId: string, items: AgendaItem[]) {
  return items.filter(i => i.barberId === barberId && i.status !== 'cancelada');
}

export function isFree(date: string, barberId: string, start: number, minutes: number, items: AgendaItem[]) {
  const b = BARBERS.find(x => x.id === barberId);
  const h = hoursFor(date);
  if (!b || !h || !isWorking(b, date)) return false;
  if (start < h.open || start + minutes > h.close) return false;
  if (h.lunch && overlaps(start, start + minutes, h.lunch[0], h.lunch[1])) return false;
  if (date === todayKey() && start <= nowMinutes() + 15) return false;
  return !busy(date, barberId, items).some(i => overlaps(start, start + minutes, i.start, i.end));
}

/** Horas posibles del día para un servicio. barberId 'any' = libre con cualquiera. Omite horas ya pasadas. */
export function slotOptions(date: string, barberId: string, minutes: number, items: AgendaItem[]): SlotOption[] {
  const h = hoursFor(date);
  if (!h) return [];
  const ids = barberId === 'any' ? BARBERS.map(b => b.id) : [barberId];
  if (!ids.some(id => isWorking(BARBERS.find(b => b.id === id)!, date))) return [];
  const out: SlotOption[] = [];
  const isToday = date === todayKey();
  const now = nowMinutes();
  for (let t = h.open; t + minutes <= h.close; t += 30) {
    if (h.lunch && overlaps(t, t + minutes, h.lunch[0], h.lunch[1])) continue;
    if (isToday && t <= now + 15) continue;
    out.push({ start: t, free: ids.some(id => isFree(date, id, t, minutes, items)) });
  }
  return out;
}

/** Para «cualquiera disponible»: el barbero libre con menos citas ese día. */
export function pickBarber(date: string, start: number, minutes: number, items: AgendaItem[]) {
  const free = BARBERS.filter(b => isFree(date, b.id, start, minutes, items));
  free.sort((a, b) => busy(date, a.id, items).length - busy(date, b.id, items).length);
  return free[0]?.id ?? null;
}

import { useCallback, useEffect, useState } from 'react';
import type { Appointment, Profile, Status } from './types';
import type { Overrides } from './schedule';
import { hoursFor, isWorking } from './schedule';
import { addDays, todayKey } from './dates';
import { BARBERS } from '../data/catalog';

const KEY = 'navaja:datos:v1';

export type Data = { appts: Appointment[]; overrides: Overrides; profile: Profile | null };

/** Busca el día abierto más cercano (hacia delante o hacia atrás) en que trabaja el barbero. */
function openDay(from: string, dir: 1 | -1, barberId: string) {
  const b = BARBERS.find(x => x.id === barberId)!;
  let d = from;
  for (let i = 0; i < 10 && !(hoursFor(d) && isWorking(b, d)); i++) d = addDays(d, dir);
  return d;
}

function seed(): Data {
  const t = todayKey();
  const profile: Profile = { name: 'Daniel Ortega', phone: '612 345 678', email: 'daniel.ortega@correo.es' };
  const base = { client: profile.name, phone: profile.phone, email: profile.email, mine: true, source: 'web' as const };
  const up = openDay(addDays(t, 2), 1, 'mateo');
  const upStart = hoursFor(up)!.close - 120;
  return {
    profile,
    overrides: {},
    appts: [
      { ...base, id: 'a1', code: 'NV-4821', serviceId: 'combo', barberId: 'mateo', date: up, start: upStart, status: 'confirmada', note: 'Degradado bajo, barba igual que la última vez.', createdAt: Date.now() - 864e5 * 3 },
      { ...base, id: 'a2', code: 'NV-3907', serviceId: 'fade', barberId: 'andres', date: openDay(addDays(t, -12), -1, 'andres'), start: 11 * 60, status: 'atendida', createdAt: Date.now() - 864e5 * 20 },
      { ...base, id: 'a3', code: 'NV-3311', serviceId: 'barba', barberId: 'leo', date: openDay(addDays(t, -26), -1, 'leo'), start: 12 * 60, status: 'cancelada', createdAt: Date.now() - 864e5 * 30 },
      { ...base, id: 'a4', code: 'NV-2876', serviceId: 'corte', barberId: 'mateo', date: openDay(addDays(t, -41), -1, 'mateo'), start: 10 * 60 + 30, status: 'atendida', createdAt: Date.now() - 864e5 * 45 },
    ],
  };
}

function load(): Data {
  try {
    const raw = localStorage.getItem(KEY);
    if (raw) {
      const d = JSON.parse(raw) as Data;
      if (Array.isArray(d.appts)) return d;
    }
  } catch { /* sin almacenamiento */ }
  return seed();
}

export const newCode = () => `NV-${Math.floor(1000 + Math.random() * 8999)}`;

export function useStore() {
  const [data, setData] = useState<Data>(load);

  useEffect(() => {
    try { localStorage.setItem(KEY, JSON.stringify(data)); } catch { /* sin almacenamiento */ }
  }, [data]);

  const book = useCallback((a: Appointment, profile: Profile) => {
    setData(d => ({ ...d, profile, appts: [...d.appts, a] }));
  }, []);

  const reschedule = useCallback((id: string, patch: Pick<Appointment, 'date' | 'start' | 'barberId'>) => {
    setData(d => ({ ...d, appts: d.appts.map(a => (a.id === id ? { ...a, ...patch, status: 'confirmada' } : a)) }));
  }, []);

  /** Cambia el estado de una cita guardada o de una generada (vía overrides). */
  const setStatus = useCallback((id: string, status: Status) => {
    setData(d =>
      d.appts.some(a => a.id === id)
        ? { ...d, appts: d.appts.map(a => (a.id === id ? { ...a, status } : a)) }
        : { ...d, overrides: { ...d.overrides, [id]: status } },
    );
  }, []);

  const reset = useCallback(() => setData(seed()), []);

  return { ...data, book, reschedule, setStatus, reset };
}

export type Store = ReturnType<typeof useStore>;

export type Status = 'confirmada' | 'atendida' | 'no-show' | 'cancelada';
export type Source = 'web' | 'teléfono' | 'en local';
export type Route = 'inicio' | 'reservar' | 'mis-citas' | 'agenda';

export type Service = {
  id: string;
  name: string;
  desc: string;
  minutes: number;
  price: number;
  popular?: boolean;
};

export type Barber = {
  id: string;
  name: string;
  short: string;
  role: string;
  years: number;
  rating: number;
  photo: string;
  specialties: string[];
  /** Días libres (0 = domingo … 6 = sábado) */
  offDays: number[];
};

export type Appointment = {
  id: string;
  code: string;
  serviceId: string;
  barberId: string;
  date: string; // AAAA-MM-DD
